import solution
import pytest

def test_empty_text_returns_empty_list():
    """Empty text -> []"""
    assert solution.wrap("", 10) == []

def test_collapses_whitespace_and_no_leading_trailing_spaces():
    """Collapse runs of whitespace and ensure no line has leading/trailing spaces"""
    assert solution.wrap("  hello   \t\tworld\n\nfoo  ", 10) == ["hello world", "foo"]

def test_greedy_wrap_fills_lines_as_much_as_possible():
    """Greedy wrap: fill line as much as possible without exceeding width"""
    assert solution.wrap("a b c d e", 3) == ["a b", "c d", "e"]

def test_word_longer_than_width_goes_on_own_line():
    """A word longer than width is placed on its own line unbroken"""
    assert solution.wrap("short verylongword here", 5) == ["short", "verylongword", "here"]

def test_tabs_and_newlines_treated_as_whitespace():
    """Tabs and newlines are treated as whitespace and collapsed"""
    assert solution.wrap("foo\t\tbar\n\nbaz", 10) == ["foo bar", "baz"]

def test_each_line_has_no_leading_or_trailing_spaces():
    """Each line returned has no leading or trailing spaces"""
    result = solution.wrap("  start middle   end  ", 10)
    for line in result:
        assert not line.startswith(' ') and not line.endswith(' ')

def test_exact_width_line_is_returned_without_extra_space():
    """A line that exactly fits the width is returned as-is"""
    assert solution.wrap("ab cd", 5) == ["ab cd"]
